ke("diagnostics");check(opened==2,"Diagnostic off can open existing logs");
 HelpDialog popup(font_,skin_,toolIcons_,false,[](const std::string&){return U"";},[](const std::string& id){const auto* d=shortcuts::find(id);return d?d->label:unicodeText(id);},menuCommands_.enabled("diagnostics"));popup.setDisplay(display(),false);const auto area=bounds();popup.setBounds({area.x+12*uiScale,area.y+12*uiScale,std::min(area.w-24*uiScale,600*uiScale),std::min(area.h-24*uiScale,400*uiScale)});ui::Timer timer(120,&popup);timer.Tick.connect([&]{timer.stop();writeSmokeFrame(popup.display()->nativeSurface().get(),assets_.parent_path()/"diagnostics-help-smoke.bmp");popup.smokeDiagnostics();});timer.start();popup.openWindowInForeground();timer.stop();check(popup.requestedAction()==2,"Help actual diagnostic footer requests close then launch");menuCommands_.invoke("diagnostics");check(opened==3&&document.historyPosition()==history,"Help diagnostic opens actual service without document edit");diagnosticFolderOpener_={};diagnosticExportChooser_={};diagnostics_->mode(0);requestFocus();refresh();
